}

http protocol "https" { # TLS certificates for all f3s services tls keypair f3s.foo.zone tls keypair www.f3s.foo.zone tls keypair standby.f3s.foo.zone tls keypair anki.f3s.foo.zone tls keypair www.anki.f3s.foo.zone tls keypair standby.anki.f3s.foo.zone tls keypair bag.f3s.foo.zone tls keypair www.bag.f3s.foo.zone tls keypair standby.bag.f3s.foo.zone tls keypair flux.f3s.foo.zone tls keypair www.flux.f3s.foo.zone tls keypair standby.flux.f3s.foo.zone tls keypair audiobookshelf.f3s.foo.zone tls keypair www.audiobookshelf.f3s.foo.zone tls keypair standby.audiobookshelf.f3s.foo.zone tls keypair gpodder.f3s.foo.zone tls keypair www.gpodder.f3s.foo.zone tls keypair standby.gpodder.f3s.foo.zone tls keypair radicale.f3s.foo.zone tls keypair www.radicale.f3s.foo.zone tls keypair standby.radicale.f3s.foo.zone tls keypair vault.f3s.foo.zone tls keypair www.vault.f3s.foo.zone tls keypair standby.vault.f3s.foo.zone tls keypair syncthing.f3s.foo.zone tls keypair www.syncthing.f3s.foo.zone tls keypair standby.syncthing.f3s.foo.zone tls keypair uprecords.f3s.foo.zone tls keypair www.uprecords.f3s.foo.zone tls keypair standby.uprecords.f3s.foo.zone
# Explicitly route non-f3s hosts to localhost match request header "Host" value "foo.zone" forward to <localhost> match request header "Host" value "www.foo.zone" forward to <localhost> match request header "Host" value "dtail.dev" forward to <localhost> # ... other non-f3s hosts ...
# NOTE: f3s hosts have NO match rules here! # They use relay-level failover (f3s -> localhost backup) # See the relay configuration below for automatic failover details }

# NEW configuration - supports automatic failover http protocol "https" { # Explicitly route non-f3s hosts to localhost match request header "Host" value "foo.zone" forward to <localhost> match request header "Host" value "dtail.dev" forward to <localhost> # ... other non-f3s hosts ...
# f3s hosts have NO protocol rules - they use relay-level failover # (no match rules for f3s.foo.zone, anki.f3s.foo.zone, etc.) }
relay "https4" { # f3s FIRST (with health checks), localhost as BACKUP forward to <f3s> port 80 check tcp forward to <localhost> port 8080 }

# OpenBSD httpd.conf
# Fallback for f3s hosts - serve fallback page for ALL paths
server "f3s.foo.zone" {
  listen on * port 8080
  log style forwarded
  location * {
    # Rewrite all requests to /index.html to show fallback page regardless of path
    request rewrite "/index.html"
    root "/htdocs/f3s_fallback"
  }
}

server "anki.f3s.foo.zone" {
  listen on * port 8080
  log style forwarded
  location * {
    request rewrite "/index.html"
    root "/htdocs/f3s_fallback"
  }
}

# ... similar blocks for all f3s hostnames ...

# k3s nodes backend table
table <k3s_nodes> { 192.168.1.120 192.168.1.121 192.168.1.122 }

# TCP forwarding to Traefik (no TLS termination)
relay "lan_http" {
    listen on 192.168.1.138 port 80
    forward to <k3s_nodes> port 80 check tcp
}

relay "lan_https" {
    listen on 192.168.1.138 port 443
    forward to <k3s_nodes> port 443 check tcp
}

